"use client";

import { RadioGroup as RadioGroupPrimitive } from "@base-ui/react/radio-group";
import { Radio as RadioPrimitive } from "@base-ui/react/radio";

import { cn } from "@/lib/utils";
import { controlChecked, controlUnchecked } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/** Playful console RadioGroup: a column of choices with 0.75rem between them. */
function RadioGroup({
  className,
  ...props
}: WithClassName<RadioGroupPrimitive.Props>) {
  return (
    <RadioGroupPrimitive
      data-slot="radio-group"
      className={cn("grid gap-3", className)}
      {...props}
    />
  );
}
RadioGroup.displayName = "RadioGroup";

/**
 * Playful console RadioGroupItem: a round white key with an olive edge and a
 * thin slab. Selected, it turns into the orange key of the primary button
 * with a dark dot at its centre.
 */
function RadioGroupItem({
  className,
  ...props
}: WithClassName<RadioPrimitive.Root.Props>) {
  return (
    <RadioPrimitive.Root
      data-slot="radio-group-item"
      className={cn(
        "inline-flex items-center justify-center aspect-square size-4.5 shrink-0 rounded-full",
        controlUnchecked,
        "transition-[background-color,border-color,box-shadow] duration-fast ease-out",
        "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
        "data-[disabled]:cursor-not-allowed data-[disabled]:bg-secondary data-[disabled]:shadow-none",
        controlChecked,
        className,
      )}
      {...props}
    >
      <RadioPrimitive.Indicator
        data-slot="radio-group-indicator"
        className="flex size-full items-center justify-center"
      >
        <span className="block size-1.5 rounded-full bg-primary-foreground" />
      </RadioPrimitive.Indicator>
    </RadioPrimitive.Root>
  );
}
RadioGroupItem.displayName = "RadioGroupItem";

export { RadioGroup, RadioGroupItem };
